        public static FactoryLease GetActivationFactory(ref nint moduleCache, ref nint factoryCache, string classId, Guid iid)
        {
            s_mta ??= new MtaUsage();
            nint requested = factoryCache;
            if (requested != 0)
            {
                return new FactoryLease(requested, 0);
            }
            nint factory = LoadActivationFactory(ref moduleCache, classId);
            try
            {
                Com.Check(Com.QueryInterface(factory, &iid, &requested));
            }
            finally
            {
                _ = Com.Release(factory);
            }
            Guid iidAgile = s_iagile;
            nint agile;
            if (Com.QueryInterface(requested, &iidAgile, &agile) >= 0)
            {
                _ = Com.Release(agile);
                factoryCache = requested;
                return new FactoryLease(requested, 0);
            }
            return new FactoryLease(requested, requested);
        }

        private static nint LoadActivationFactory(ref nint moduleCache, string classId)
        {
            nint module = moduleCache;
            if (module == 0)
            {
                module = LoadModule(classId);
                moduleCache = module;
            }
            nint factory = 0;
            int hr = unchecked((int)0x80040111);
            fixed (char* id = classId)
            {
                Interop.HstringHeader header;
                nint hstring = Interop.CreateStringReference((ushort*)id, (uint)classId.Length, &header);
                if (module != 0)
                {
                    nint proc = Interop.GetProcAddress(module, "DllGetActivationFactory");
                    if (proc != 0)
                    {
                        hr = ((delegate* unmanaged<nint, nint*, int>)proc)(hstring, &factory);
                    }
                }
                if (hr < 0)
                {
                    Guid iid = new Guid(0x00000035, 0x0000, 0x0000, 0xc0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x46);
                    hr = Interop.RoGetActivationFactory(hstring, &iid, &factory);
                }
            }
            Com.Check(hr);
            return factory;
        }

        private static nint LoadModule(string classId)
        {
            nint module = 0;
            string name = classId;
            while (true)
            {
                int dot = name.LastIndexOf('.');
                if (dot < 0)
                {
                    break;
                }
                name = name.Substring(0, dot);
                module = Interop.LoadLibrary(name + ".dll");
                if (module != 0)
                {
                    break;
                }
            }
            return module;
        }

        private sealed class MtaUsage
        {
            private nint _cookie;

            public MtaUsage()
            {
                nint cookie;
                Com.Check(Interop.CoIncrementMTAUsage(&cookie));
                _cookie = cookie;
            }

            ~MtaUsage()
            {
                if (_cookie != 0)
                {
                    _ = Interop.CoDecrementMTAUsage(_cookie);
                }
            }
        }
    }

